// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        vm.prank(0x000000000000000000000000000000000000bEEF, 0x000000000000000000000000000000000000bEEF);
        c = new XBORNID();
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        try c.XBornID() {} catch { return; }
        uint256 bal;
        try c.balanceOf(msg.sender) returns (uint256 __r) { bal = __r; } catch { return; }
        uint256 dist;
        try c.totalDistributed() returns (uint256 __r) { dist = __r; } catch { return; }
        assertTrue(bal == dist);
    }

    function testFuzz_run(address caller) public {
        vm.assume(uint160(caller) > 255 && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller);
    }

    receive() external payable {}
}
